import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;

public class Solution {
    record Pagamento(long id, String chaveIdempotencia, long valorCentavos, String status) {}
    record Lancamento(long pagamentoId, String tipo, long valorCentavos) {}

    static class ConflitoPagamentoException extends RuntimeException {
        ConflitoPagamentoException(String message) { super(message); }
    }

    static class PagamentoService {
        private final Map<Long, Pagamento> pagamentos = new HashMap<>();
        private final Map<String, Long> porChave = new HashMap<>();
        private final List<Lancamento> ledger = new ArrayList<>();
        private long proximoId = 1;

        Pagamento pagar(String chaveIdempotencia, long valorCentavos) {
            if (chaveIdempotencia == null || chaveIdempotencia.isBlank()) {
                throw new IllegalArgumentException("chave de idempotencia obrigatoria");
            }
            if (valorCentavos <= 0) throw new IllegalArgumentException("valor invalido");

            Long idExistente = porChave.get(chaveIdempotencia);
            if (idExistente != null) {
                var existente = pagamentos.get(idExistente);
                if (existente.valorCentavos() != valorCentavos) {
                    throw new ConflitoPagamentoException(
                        "chave " + chaveIdempotencia + " ja usada com outro valor");
                }
                return existente;
            }

            long id = proximoId++;
            var pagamento = new Pagamento(id, chaveIdempotencia, valorCentavos, "AUTORIZADO");
            pagamentos.put(id, pagamento);
            porChave.put(chaveIdempotencia, id);
            ledger.add(new Lancamento(id, "AUTORIZACAO", valorCentavos));
            return pagamento;
        }

        Pagamento capturar(long pagamentoId) {
            var atual = buscar(pagamentoId);
            if (!"AUTORIZADO".equals(atual.status())) {
                throw new IllegalStateException("captura invalida para status " + atual.status());
            }
            var novo = new Pagamento(atual.id(), atual.chaveIdempotencia(),
                atual.valorCentavos(), "CAPTURADO");
            pagamentos.put(pagamentoId, novo);
            ledger.add(new Lancamento(pagamentoId, "CAPTURACAO", atual.valorCentavos()));
            return novo;
        }

        Pagamento estornar(long pagamentoId) {
            var atual = buscar(pagamentoId);
            if (!"CAPTURADO".equals(atual.status())) {
                throw new IllegalStateException("estorno invalido para status " + atual.status());
            }
            var novo = new Pagamento(atual.id(), atual.chaveIdempotencia(),
                atual.valorCentavos(), "ESTORNADO");
            pagamentos.put(pagamentoId, novo);
            ledger.add(new Lancamento(pagamentoId, "ESTORNO", -atual.valorCentavos()));
            return novo;
        }

        Pagamento buscar(long pagamentoId) {
            var pagamento = pagamentos.get(pagamentoId);
            if (pagamento == null) {
                throw new NoSuchElementException("pagamento " + pagamentoId + " nao encontrado");
            }
            return pagamento;
        }

        List<Lancamento> lancamentos() { return List.copyOf(ledger); }
    }
}

