import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.List;

class SolutionTest {
    @Test void pagamentoUnicoPorChave() {
        var s = new Solution.PagamentoService();
        var p1 = s.pagar("k1", 1000);
        var p2 = s.pagar("k1", 1000);
        assertEquals(p1, p2);
        assertEquals(1, s.lancamentos().size());
        assertEquals("AUTORIZADO", p2.status());
    }

    @Test void mesmaChaveOutroValorConflita() {
        var s = new Solution.PagamentoService();
        s.pagar("k1", 1000);
        assertThrows(Solution.ConflitoPagamentoException.class, () -> s.pagar("k1", 2000));
        assertEquals(1, s.lancamentos().size());
    }

    @Test void fluxoCompleto() {
        var s = new Solution.PagamentoService();
        var p = s.pagar("k1", 500);
        assertEquals(1, p.id());

        var capturado = s.capturar(p.id());
        assertEquals("CAPTURADO", capturado.status());

        var estornado = s.estornar(p.id());
        assertEquals("ESTORNADO", estornado.status());

        assertEquals(List.of(
            new Solution.Lancamento(1, "AUTORIZACAO", 500),
            new Solution.Lancamento(1, "CAPTURACAO", 500),
            new Solution.Lancamento(1, "ESTORNO", -500)
        ), s.lancamentos());
    }

    @Test void transicoesInvalidas() {
        var s = new Solution.PagamentoService();
        s.pagar("k1", 100);
        assertThrows(IllegalStateException.class, () -> s.estornar(1));
        s.capturar(1);
        assertThrows(IllegalStateException.class, () -> s.capturar(1));
        s.estornar(1);
        assertThrows(IllegalStateException.class, () -> s.estornar(1));
        assertEquals(3, s.lancamentos().size());
    }

    @Test void buscaInexistente() {
        var s = new Solution.PagamentoService();
        assertThrows(java.util.NoSuchElementException.class, () -> s.buscar(42));
    }

    @Test void chavesDiferentesCriamPagamentosDiferentes() {
        var s = new Solution.PagamentoService();
        var p1 = s.pagar("k1", 100);
        var p2 = s.pagar("k2", 100);
        assertNotEquals(p1.id(), p2.id());
        assertEquals(2, s.lancamentos().size());
    }

    @Test void validacoes() {
        var s = new Solution.PagamentoService();
        assertThrows(IllegalArgumentException.class, () -> s.pagar("", 100));
        assertThrows(IllegalArgumentException.class, () -> s.pagar("k1", 0));
        assertThrows(IllegalArgumentException.class, () -> s.pagar("k1", -5));
    }

    @Test void lancamentosSaoImutaveis() {
        var s = new Solution.PagamentoService();
        s.pagar("k1", 100);
        assertThrows(UnsupportedOperationException.class,
            () -> s.lancamentos().add(new Solution.Lancamento(1, "X", 1)));
    }
}
